import {readFileSync,writeFileSync} from 'node:fs';
import {createRequire} from 'node:module';
import {dirname,join} from 'node:path';
const require=createRequire(import.meta.url),root=dirname(require.resolve('leaflet/package.json'));
const js=readFileSync(join(root,'dist/leaflet.js'),'utf8').replace(/\/\/# sourceMappingURL=.*$/m,'');
const css=readFileSync(join(root,'dist/leaflet.css'),'utf8');
writeFileSync(new URL('../apps/mobile/src/components/maps/leaflet-vendor.ts',import.meta.url),'// Generated by scripts/build-map-assets.mjs. Leaflet BSD-2-Clause; see docs/licenses/leaflet-LICENSE.txt.\nexport const leafletScript='+JSON.stringify(js)+';\nexport const leafletCss='+JSON.stringify(css)+';\n');
writeFileSync(new URL('../docs/licenses/leaflet-LICENSE.txt',import.meta.url),readFileSync(join(root,'LICENSE')));
